def _motif_shape(motif):
    """`(trimmed motif, pattern)`, or None when the string is not a `(d1, spacer, d2)` motif.

    Leading and trailing `N` are not part of a motif, and a string with two gaps is not a shape
    any pattern can express.
    """
    motif = motif.strip("N")
    if not motif:
        return None
    runs = re.findall(r"N+|[^N]+", motif)
    if len(runs) == 1:
        return motif, (len(motif), 0, 0)
    if len(runs) == 3:
        return motif, (len(runs[0]), len(runs[1]), len(runs[2]))
    return None


def _parent_motifs(motif, pattern):
    """Every motif `motif` could be a one-base extension of.

    The inverse of `_undefined_positions`: the base it adds sits at an end or at a spacer edge,
    so giving up one of those four bases recovers the motif it extends. Checking these against
    the candidates is the same question as asking, of every shorter candidate, whether this motif
    extends it -- at a handful of lookups instead of a comparison per pair.

    Returns the motif strings, without their patterns -- a caller matching against a set of
    candidate strings does not need them.
    """
    d1, spacer, d2 = pattern
    raw = [motif[1:], motif[:-1]]
    if spacer:
        raw.append(motif[:d1 - 1] + "N" + motif[d1:])                  # widen the gap leftwards
        raw.append(motif[:d1 + spacer] + "N" + motif[d1 + spacer + 1:])  # ... and rightwards
    out = []
    for s in raw:
        shaped = _motif_shape(s)
        if shaped is not None and shaped[0] != motif:
            out.append(shaped[0])
    return sorted(set(out))

# %% ../nbs/00_core.ipynb #ed02ec03
def _relax_positions(
    motif:str, # the candidate
    pattern:tuple, # its `(d1, spacer, d2)` shape
)->list: # positions in `motif`
    "The defined bases of `motif` that can be put back to N, leaving a valid pattern."
    d1, spacer, d2 = pattern
    if spacer == 0:
        return list(range(len(motif)))
    positions = set()
    if d1 >= 2:
        positions |= {0, d1 - 1}
    if d2 >= 2:
        positions |= {d1 + spacer, len(motif) - 1}
    return sorted(positions)


_LR_THRESHOLD = 10   # a set of plasmids is classified when one model fits it this many times better


def _site_or_background(n, k, site_rate, background_rate):
    """'site', 'non-site' or 'unknown' for a set of `n` plasmids of which `k` are depleted.

    Compares two models of them -- depleted at `site_rate`, or at `background_rate` -- by their
    log-likelihood ratio, which grows with `n`, so it is also the confidence: the set is
    classified only when one model fits `_LR_THRESHOLD` times better. Rates must lie strictly
    between 0 and 1; a site rate no higher than background gives 'unknown'.
    """
    if site_rate <= background_rate:
        return "unknown"
    llr = (k * np.log(site_rate / background_rate)
           + (n - k) * np.log((1 - site_rate) / (1 - background_rate)))
    cut = np.log(_LR_THRESHOLD)
    return "site" if llr > cut else "non-site" if llr < -cut else "unknown"


def _classify_bases(
    profile:list, # `(motif, n, score, background)` for the four bases, from `_variant_profile`
    motif:str, # the candidate, one of the four
    min_support:int, # a base carried by fewer plasmids is not classified
)->dict|None: # other motif -> class, if carried `min_support` times; None if `motif` is not
    "'site', 'non-site' or 'unknown' for each base other than `motif`'s at one position."
    own = next((p for p in profile if p[0] == motif), None)
    if own is None or own[1] < min_support:
        return None
    others = [p for p in profile if p[0] != motif and p[1] >= min_support]
    clip = lambda rate, n: min(max(rate, 0.5 / n), 1 - 0.5 / n)   # keep the logs finite

    def classify(site_rate):
        return {m: _site_or_background(n, round(s * n), site_rate, b) for m, n, s, b in others}

    first = classify(clip(own[2], own[1]))
    pooled = [own] + [p for p in others if first[p[0]] == "site"]
    n = sum(p[1] for p in pooled)
    return classify(clip(sum(p[1] * p[2] for p in pooled) / n, n))


def _classify_positions(
    motif:str, # the candidate; IUPAC letters allowed at its defined positions
    positions:list, # defined positions of `motif` to classify
    pattern:tuple, # its `(d1, spacer, d2)` shape
    encoded_library:tuple, # as for `_is_mixture`
    fc_values:np.ndarray, # as for `_is_mixture`
    background:np.ndarray, # as for `_is_mixture`
    log2fc_thr:float=-1, # as for `_is_mixture`
    min_support:int=5, # as for `_is_mixture`
    totals:dict|None=None, # as for `_is_mixture`
)->dict: # position -> {base: (class, carriers)}; empty at each when `motif` has too few carriers
    "For each position, the class and carriers of every base `motif` does not allow there."
    alts = {i: [motif[:i] + b + motif[i + 1:] for b in "ACGT" if b not in _IUPAC_EXPAND[motif[i]]]
            for i in positions}
    motifs = [motif] + [v for vs in alts.values() for v in vs]
    if _encode_motif(motif, pattern) is not None:          # A, C, G and T only: the scan's counts
        profile = _variant_profile(motifs, pattern, encoded_library, fc_values, background,
                                  log2fc_thr, totals)
    else:
        profile = _union_profile(motifs, pattern, encoded_library, fc_values, background,
                                 log2fc_thr)
    stats = dict(zip(motifs, profile))
    out = {}
    for i, vs in alts.items():
        classes = _classify_bases([profile[0]] + [stats[v] for v in vs], motif, min_support) or {}
        out[i] = {v[i]: (classes[v], stats[v][1]) for v in vs if v in classes}
    return out


def _is_over_specified(
    motif:str, # the candidate
    pattern:tuple, # its `(d1, spacer, d2)` shape
    encoded_library:tuple, # as for `_is_mixture`
    fc_values:np.ndarray, # as for `_is_mixture`
    background:np.ndarray, # as for `_is_mixture`
    log2fc_thr:float=-1, # as for `_is_mixture`
    min_support:int=5, # as for `_is_mixture`
    totals:dict|None=None, # as for `_is_mixture`
)->bool: # True when, at one of `_relax_positions`, every other base is site-like
    "Does `motif` have a defined base at which every other base behaves like the site?"
    by_position = _classify_positions(motif, _relax_positions(motif, pattern), pattern,
                                     encoded_library, fc_values, background, log2fc_thr,
                                     min_support, totals)
    return any(classes and all(c == "site" for c, _ in classes.values())
               for classes in by_position.values())

# %% ../nbs/00_core.ipynb #dd9f3316
def _patterns(df):
    """The 'pattern' column as `(d1, spacer, d2)` tuples; None where it is missing or unreadable."""
    if "pattern" not in df.columns:
        return [None] * len(df)
    out = []
    for p in df["pattern"]:
        try:
            out.append(tuple(ast.literal_eval(p) if isinstance(p, str) else p) or None)
        except (ValueError, SyntaxError, TypeError):
            out.append(None)
    return out


def _motif_instances(motif, pattern):
    """The motifs of A, C, G and T that `motif` stands for: every IUPAC letter at a defined position
    expanded, the spacer left as it is."""
    d1, spacer, _ = pattern
    gap = range(d1, d1 + spacer)
    choices = [c if i in gap else sorted(_IUPAC_EXPAND[c]) for i, c in enumerate(motif)]
    return ["".join(t) for t in product(*choices)]


def _instance_presence(encoded, motifs, patterns, insert=None):
    """`_motif_presence_matrix` for motifs with IUPAC letters: a plasmid carries a motif when it
    carries one of its instances (`_motif_instances`), on either strand. Returns `(matrix, handled)`,
    or `(matrix, inside, handled)` with `insert` (as for `_motif_presence_matrix`); a motif whose
    pattern is unknown, or which does not fit it, is not handled."""
    inst = [_motif_instances(m, p) if p is not None else [] for m, p in zip(motifs, patterns)]
    # Each distinct instance is looked up once, however many motifs share it.
    keys = list(dict.fromkeys((x, p) for xs, p in zip(inst, patterns) for x in xs))
    col = {k: j for j, k in enumerate(keys)}
    *found, ok = _motif_presence_matrix(encoded, [x for x, _ in keys], [p for _, p in keys], insert)
    out = [np.zeros((encoded[0].shape[0], len(motifs)), dtype=bool) for _ in found]
    handled = np.zeros(len(motifs), dtype=bool)
    for j, (xs, p) in enumerate(zip(inst, patterns)):
        cols = [col[(x, p)] for x in xs]
        if cols and ok[cols].all():
            for o, has in zip(out, found):
                o[:, j] = has[:, cols].any(axis=1)
            handled[j] = True
    return (*out, handled)


def _carriers(
    encoded:tuple, # `(fwd, rc)` from `encode_library`
    motifs:list, # motif strings, IUPAC letters allowed
    patterns:list, # each motif's `(d1, spacer, d2)`, or None where unknown
    log2fc_series:pd.Series, # log2FC indexed by insert, read by the regex fallback
    left_context:str, # vector sequence 5' of the insert
    right_context:str, # vector sequence 3' of the insert
    inside:bool=False, # also return the carriers with a site wholly inside the insert
)->np.ndarray: # boolean, (n_sequences, n_motifs); with `inside`, `(carriers, internal carriers)`
    "Which plasmids carry each motif, on either strand."
    insert = (len(left_context), len(right_context),
              np.array([len(s) for s in log2fc_series.index])) if inside else None
    *found, handled = _instance_presence(encoded, motifs, patterns, insert)
    for j in np.flatnonzero(~handled):
        found[0][:, j] = _get_filter_for_motif(
            log2fc_series, motifs[j], left_context, right_context).to_numpy()
        if inside:
            found[1][:, j] = _get_filter_for_motif(log2fc_series, motifs[j], "", "").to_numpy()
    return tuple(found) if inside else found[0]

# %% ../nbs/00_core.ipynb #8bc15550
def _filter_redundant_patterns(
    df:pd.DataFrame, # candidates, with 'motif' and 'pattern'
    log2fc_series:pd.Series, # log2FC indexed by insert
    left_context:str, # vector sequence 5' of the insert
    right_context:str, # vector sequence 3' of the insert
    log2fc_thr:float=-1, # a plasmid is depleted below this
    score_thr:float=0.5, # the candidates' bar, reused for a variant's and a mixture's spread
    min_support:int=5, # a variant on fewer plasmids than this is not judged
    encoded:tuple|None=None, # the library from `encode_library`, if the caller has it
    totals:dict|None=None, # shared pattern totals, as for `_variant_profile`
    background:np.ndarray|None=None, # expected depletion per plasmid; default `plasmid_background`
)->pd.DataFrame: # `df` without the redundant rows, in the original row order
    "Keep one description per site, by rules 1 to 3."
    if df.empty:
        return df
    motifs = df["motif"].tolist()
    pats = _patterns(df)
    if encoded is None:
        encoded = encode_library(get_lib_seq_context(log2fc_series.index.tolist(),
                                                     left_context, right_context))
    totals = {} if totals is None else totals
    fc = log2fc_series.to_numpy()
    if background is None:
        background = plasmid_background(log2fc_series.index, fc, log2fc_thr)

    # Rule 1. A candidate whose pattern is unknown cannot be tested, and stays.
    survivors = [k for k in range(len(df)) if pats[k] is None or not _is_mixture(
        motifs[k], pats[k], encoded, fc, background, log2fc_thr, score_thr, min_support, totals)]

    # Rule 2, by lookup rather than by comparing pairs: each survivor asks whether any of the
    # four motifs it could extend is itself a survivor. Comparing every pair is quadratic, and
    # at a permissive threshold a strain can reach hundreds of thousands of candidates.
    standing = {motifs[k] for k in survivors}
    standing |= {revcomp(m) for m in standing}      # a parent may be spelled on the other strand
    keep = [k for k in survivors
            if not any(g in standing for g in _parent_motifs(motifs[k], pats[k]))]

    # Rule 3. Every variant it reads is in the candidate's own pattern, which step 2 counted.
    keep = [k for k in keep if pats[k] is None or not _is_over_specified(
        motifs[k], pats[k], encoded, fc, background, log2fc_thr, min_support, totals)]
    return df.iloc[keep]

