def _filter_explained_candidates(
    candidates_df:pd.DataFrame, # candidates, with 'motif' and optionally 'pattern'
    log2fc_series:pd.Series, # log2FC indexed by insert
    left_context:str, # vector sequence 5' of the insert
    right_context:str, # vector sequence 3' of the insert
    log2fc_thr:float=-1, # a plasmid is depleted below this
    score_thr:float=0.7, # share of a candidate's leftover plasmids that must still be depleted
    min_support:int=3, # not used; accepted so the step takes the pipeline's thresholds
    encoded:tuple|None=None, # the library from `encode_library`, if the caller has it
    p_threshold:float=0.05, # the leftover must beat its carriers' mean background at this p
    background:np.ndarray|None=None, # expected depletion per plasmid; default `plasmid_background`
    presence:np.ndarray|None=None, # each candidate's carriers (`_carriers`), if the caller has them
)->tuple: # `(kept, explanations)`: dropped motif -> (explained by, plasmids left, their score)
    "Drop candidates whose depletion is fully accounted for by stronger candidates."
    if len(candidates_df) < 2:
        return candidates_df, {}     # nothing that could explain anything

    motifs = candidates_df['motif'].tolist()
    if presence is None:
        if encoded is None:
            encoded = encode_library(
                get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
        presence = _carriers(encoded, motifs, _patterns(candidates_df), log2fc_series,
                             left_context, right_context)

    fc = log2fc_series.to_numpy()
    if background is None:
        background = plasmid_background(log2fc_series.index, fc, log2fc_thr)
    strength = []
    for j in range(len(motifs)):
        v = fc[presence[:, j]]
        strength.append(((v < log2fc_thr).mean() if len(v) else 0.0, len(v), motifs[j]))
    # Strongest first: highest depletion fraction, then MOST plasmids. Support breaks the tie, not
    # mean log2FC, because the plasmids carrying a shadow are a subset of those carrying its
    # parent, and the subset picked out by the extra bases it requires tends to be the most
    # depleted -- so on mean log2FC a shadow outranks the site it came from and is never tested
    # against it. A subset can never have more plasmids than the set it is drawn from. The motif
    # string is the final tie-break, so the outcome does not depend on row order.
    order = sorted(range(len(motifs)), key=lambda j: (-strength[j][0], -strength[j][1], strength[j][2]))

    # A leftover stands when it still reaches score_thr AND is depleted beyond its own
    # background -- the binomial null the calls are scored against, the rate being the mean
    # background of the leftover plasmids -- at the scan's own cutoff.
    def holds(alone):
        n = int(alone.sum())
        still = float((fc[alone] < log2fc_thr).mean()) if n else 0.0
        ok = n > 0 and still >= score_thr and \
            _motif_pvalues([n], [still], background[alone].sum() / n)[0] <= p_threshold
        return ok, n, still

    explanations = {}
    # The test is against the UNION of the stronger survivors: a description that overlaps
    # several co-occurring sites can keep a depleted residue against each of them separately
    # although every plasmid that carries it carries one of them.
    covered = np.zeros(presence.shape[0], dtype=bool)
    standing = []                                        # survivors, strongest first
    for x in order:
        ok, n, still = holds(presence[:, x] & ~covered)
        if not ok:
            # Name the survivor that accounts for most of X's plasmids, and say how many others
            # it took. A dropped candidate explains nothing, so it never joins `covered`.
            shared = [(int((presence[:, x] & presence[:, y]).sum()), -k, y)
                      for k, y in enumerate(standing)]
            shared = [s for s in shared if s[0] > 0]
            if shared:
                label = motifs[max(shared)[2]] + (
                    f" + {len(shared) - 1} more" if len(shared) > 1 else "")
            else:                    # fails on the plasmids that carry it; nothing to blame
                label = "(no stronger motif)"
            explanations[x] = (label, n, still)
            continue
        covered |= presence[:, x]
        standing.append(x)

    # The audit: every survivor against all the others, weakest first, one removal at a time.
    survivors = standing
    while len(survivors) > 1:
        cover = presence[:, survivors].sum(axis=1)
        for x in sorted(survivors, key=lambda j: strength[j]):
            ok, n, still = holds(presence[:, x] & (cover == 1))   # carried by x alone
            if not ok:
                overlap = max((y for y in survivors if y != x),
                              key=lambda y: int((presence[:, x] & presence[:, y]).sum()))
                explanations[x] = (motifs[overlap] + " (audit)", n, still)
                survivors.remove(x)
                break
        else:
            break

    keep = [j for j in range(len(motifs)) if j not in explanations]
    return candidates_df.iloc[keep], {motifs[x]: v for x, v in explanations.items()}

