def _canonicalise_motifs(df):
    """Put every motif in a result table on its canonical strand.

    A motif and its reverse complement have identical statistics, so rewriting the label loses
    nothing.
    """
    if df is None or df.empty or 'motif' not in df.columns:
        return df
    df = df.copy()
    flipped = df['motif'] != df['motif'].map(canonical_motif)
    df['motif'] = df['motif'].map(canonical_motif)
    # The pattern has to follow the motif. Reverse-complementing a (d1, spacer, d2) site gives
    # a (d2, spacer, d1) site, so a relabelled row whose pattern was left alone would describe
    # a string it does not hold -- and every consumer that pairs motif with pattern, such as
    # _motif_presence_matrix, would silently decline to handle it.
    if 'pattern' in df.columns:
        def _mirror(p):
            try:
                d1, sp, d2 = ast.literal_eval(p) if isinstance(p, str) else tuple(p)
            except (ValueError, SyntaxError, TypeError):
                return p
            # With no spacer the site is contiguous and (k, 0, 0) is the spelling the
            # pattern list uses, so mirroring must not turn (6, 0, 0) into (0, 0, 6).
            m = (d1 + d2, 0, 0) if sp == 0 else (d2, sp, d1)
            return str(m) if isinstance(p, str) else m
        df.loc[flipped, 'pattern'] = df.loc[flipped, 'pattern'].map(_mirror)
    return df

# %% ../nbs/00_core.ipynb #f9ba37dc
def _bimodality_coefficient(values):
    """Sarle's bimodality coefficient: (skew^2 + 1) / (kurtosis + 3(n-1)^2/((n-2)(n-3))).

    Above 5/9 the distribution is more bimodal than a uniform one. NaN below four values, where
    it is not defined, and when every value is the same.
    """
    v = np.asarray(values, dtype=float)
    v = v[np.isfinite(v)]
    n = len(v)
    if n < 4 or np.allclose(v, v[0]):
        return float("nan")
    g = skew(v, bias=False)
    k = kurtosis(v, bias=False, fisher=True)
    denom = k + 3.0 * (n - 1) ** 2 / ((n - 2) * (n - 3))
    return float((g ** 2 + 1.0) / denom) if denom > 0 else float("nan")


_BIMODALITY_BENCHMARK = 5.0 / 9.0


def _upper_group_median(values):
    """Median of the upper group when `values` are split in two at the cut that maximises the
    between-group variance (Otsu's method: two-means in one dimension, on the sorted values).

    NaN below two finite values.
    """
    v = np.sort(np.asarray(values, dtype=float))
    v = v[np.isfinite(v)]
    n = len(v)
    if n < 2:
        return float("nan")
    k = np.arange(1, n)                       # the lower group is v[:k]
    low = np.cumsum(v)[:-1]
    between = k * (n - k) * (low / k - (v.sum() - low) / (n - k)) ** 2
    return float(np.median(v[k[np.argmax(between)]:]))


def _annotate_significance(results_df, log2fc_series, left_context, right_context,
                          all_pvalues=None, log2fc_thr=-1, q_threshold=0.05, encoded=None,
                          background=None, score_thr=0.5, min_support=5, carriers=None):
    """Add fraction_depleted_lower, background, p_value, q_value, the junction columns, called,
    bimodality and bimodal to a result table.

    `fraction_depleted_lower` is the one-sided lower confidence bound on the fraction of carriers
    depleted (Clopper-Pearson, at level `q_threshold`). A candidate had to reach `score_thr` --
    most of its carriers depleted -- and a call has to show it: 5 of 10 depleted is 0.5, but its
    bound is 0.22.

    `background` is the rate at which the motif's carriers would deplete with no site involved:
    the mean over them of each plasmid's GC-matched background (`plasmid_background`, computed
    from `log2fc_series` when not given). The p-value is taken against it, as in the scan.

    `all_pvalues` are the p-values of every motif the scan tested, which is what the
    Benjamini-Hochberg correction has to be computed over -- correcting only over the handful
    that survived filtering would be meaningless.

    `bimodal` marks carriers that are a mixture of depleted and background-level plasmids: a
    bimodality coefficient above 5/9 and, when the carriers are split in two where they separate
    best, an upper group that is not depleted at `log2fc_thr`.

    `junction_share`, `internal_n`, `internal_fraction_lower` and `internal_p_value` are
    `_junction_support`. `carriers` is `_carriers(..., inside=True)` of the rows, read from
    `encoded` when not given.

    Nothing is removed. `called` marks the rows whose q-value is below `q_threshold`, whose
    `fraction_depleted_lower` reaches `score_thr`, and which are not `_junction_dependent` at
    `min_support`; the rest stay in the table so that a weak result is visible as a weak claim
    rather than silently absent (`find_restricted_motifs` returns them with `all_motifs=True`).
    """
    if results_df is None:
        return results_df
    if results_df.empty:
        # A strain with no active system is the first thing a new user runs, so the empty
        # table must have the same columns as a full one -- otherwise selecting the called
        # rows works on every strain that finds something and raises on the ones that do not.
        out = results_df.copy()
        for _c, _dt in (("fraction_depleted_lower", float), ("background", float),
                        ("p_value", float), ("q_value", float), ("junction_share", float),
                        ("internal_n", int), ("internal_fraction_lower", float),
                        ("internal_p_value", float), ("called", bool),
                        ("bimodality", float), ("bimodal", bool)):
            if _c not in out.columns:
                out[_c] = pd.Series(dtype=_dt)
        return out
    # Placed beside fraction_depleted below; dropped first so a table can be annotated again.
    out = results_df.drop(columns=["fraction_depleted_lower", "background"], errors="ignore")
    if background is None:
        background = plasmid_background(log2fc_series.index, log2fc_series.to_numpy(), log2fc_thr)
    if carriers is None:
        if encoded is None:
            encoded = encode_library(
                get_lib_seq_context(log2fc_series.index.tolist(), left_context, right_context))
        carriers = _carriers(encoded, out["motif"].tolist(), _patterns(out), log2fc_series,
                             left_context, right_context, inside=True)
    presence, inner = carriers
    # Each motif's null is its carriers' mean background, summed exactly as the scan sums it, so
    # that a reported motif's p-value is the scan's to the last bit (see `plasmid_background`).
    rate = (background @ presence) / presence.sum(axis=0)
    n = out["num_sequences"].to_numpy()
    k = np.rint(out["fraction_depleted"].to_numpy() * n)
    at = out.columns.get_loc("fraction_depleted") + 1
    out.insert(at, "fraction_depleted_lower", _depleted_lower(n, k, q_threshold))
    out.insert(at + 1, "background", rate)

    p = _motif_pvalues(out["num_sequences"].to_numpy(), out["fraction_depleted"].to_numpy(), rate)
    out["p_value"] = p
    if all_pvalues is not None and len(all_pvalues):
        # The reported motifs were tested by the scan, so their p-values are already in
        # `all_pvalues`; appending them again counted those tests twice. Only a p-value the scan
        # never produced is a new test and joins the pool. Each motif's q is then read off the
        # adjusted pool at its own p-value -- BH q-values are a non-decreasing step function of
        # p, so tied p-values share one q.
        pool = np.asarray(all_pvalues, dtype=float)
        pool = np.sort(np.concatenate([pool, p[~np.isin(p, pool)]]))
        q_pool = _benjamini_hochberg(pool)
        out["q_value"] = q_pool[np.searchsorted(pool, p, side="right") - 1]
    else:
        out["q_value"] = _benjamini_hochberg(p)
    values = log2fc_series.to_numpy()
    support = _junction_support(presence, inner, values, background, log2fc_thr, q_threshold)
    for c in support.columns:
        out[c] = support[c].to_numpy()
    out["called"] = (out["q_value"] < q_threshold) & (out["fraction_depleted_lower"] >= score_thr) \
        & ~_junction_dependent(out, score_thr, min_support, q_threshold)

    carriers = [values[presence[:, j]] for j in range(len(out))]
    out["bimodality"] = [_bimodality_coefficient(v) for v in carriers]
    # Two modes, the upper one at background: destroyed and untouched plasmids mixed. Two
    # depleted modes -- strong and very strong -- are a site, not a mixture.
    out["bimodal"] = (out["bimodality"] > _BIMODALITY_BENCHMARK) & \
        np.array([_upper_group_median(v) >= log2fc_thr for v in carriers], dtype=bool)

    return out.sort_values(["called", "q_value"], ascending=[False, True])

# %% ../nbs/00_core.ipynb #8fd90aec
def _union_profile(motifs, pattern, encoded, fc, background, log2fc_thr):
    """`_variant_profile` for motifs with IUPAC letters: each scored on the plasmids carrying any of
    its instances, which the scan's per-motif counts cannot give (a plasmid can carry two)."""
    has = _instance_presence(encoded, motifs, [pattern] * len(motifs))[0]
    n = has.sum(axis=0)
    depleted = (fc < log2fc_thr).astype(float) @ has
    bg_sum = background @ has
    return [(m, int(k), float(d / k) if k else float("nan"), float(b / k) if k else float("nan"))
            for m, k, d, b in zip(motifs, n, depleted, bg_sum)]


def _generalise_motif(
    motif:str, # a called motif
    pattern:tuple, # its `(d1, spacer, d2)` shape
    encoded_library:tuple, # as for `_is_mixture`
    fc_values:np.ndarray, # as for `_is_mixture`
    background:np.ndarray, # as for `_is_mixture`
    log2fc_thr:float=-1, # as for `_is_mixture`
    min_support:int=5, # as for `_is_mixture`
    totals:dict|None=None, # as for `_is_mixture`
)->str: # the merged motif, or `motif` itself when no position is degenerate
    "`motif` with each degenerate position written as the IUPAC letter of its site-like bases."
    defined = [i for i, c in enumerate(motif) if c != "N"]
    while True:
        best = None
        for i, classes in _classify_positions(motif, defined, pattern, encoded_library, fc_values,
                                             background, log2fc_thr, min_support, totals).items():
            site = [b for b, (c, _) in classes.items() if c == "site"]
            # Every other base site-like is an uninformative base (rule 3), not a degenerate one.
            if site and len(site) < len(classes):
                n = sum(classes[b][1] for b in site)
                if best is None or n > best[0]:
                    best = (n, i, site)
        if best is None:
            return motif
        _, i, site = best
        motif = motif[:i] + _IUPAC_COLLAPSE[_IUPAC_EXPAND[motif[i]] | frozenset(site)] + motif[i + 1:]

# %% ../nbs/00_core.ipynb #fcb77d69
def _is_instance(specific, general):
    """Does `general` allow every base of `specific`, on one strand or the other?"""
    allows = lambda s: len(s) == len(general) and all(
        _IUPAC_EXPAND[a] <= _IUPAC_EXPAND[b] for a, b in zip(s, general))
    return allows(specific) or allows(revcomp(specific))


def _motif_rows(motifs, patterns, log2fc_series, left_context, right_context, encoded, log2fc_thr):
    """Result-table rows -- support, fraction depleted, mean log2FC, pattern -- read off each
    motif's carriers."""
    has = _carriers(encoded, motifs, patterns, log2fc_series, left_context, right_context)
    fc = log2fc_series.to_numpy(dtype=float)
    n = has.sum(axis=0)
    return pd.DataFrame({"motif": motifs,
                         "fraction_depleted": (fc < log2fc_thr).astype(float) @ has / n,
                         "num_sequences": n, "avg_log2fc": fc @ has / n,
                         "pattern": [str(p) for p in patterns]})


def _merge_degenerate_calls(table, log2fc_series, left_context, right_context, encoded, background,
                           all_pvalues, log2fc_thr=-1, q_threshold=0.05, score_thr=0.5,
                           min_support=5, totals=None):
    """Report each degenerate site as one IUPAC motif, in place of its called variants.

    Every called row is generalised (`_generalise_motif`); each distinct merged motif that is not an
    instance of another is scored on its own carriers (`_annotate_significance`, against
    `all_pvalues`). A called merged motif replaces the rows that are instances of it and are called
    or `_junction_dependent`: such a variant lacks internal sites of its own, and the merged motif
    passed that test on its carriers, which include the variant's.

    Args:
        table (pd.DataFrame): the scored result table, from `_annotate_significance`.
        log2fc_series (pd.Series): log2 fold change, indexed by insert sequence, as scored.
        left_context (str), right_context (str): the vector flanks.
        encoded (tuple): the library from `encode_library`.
        background (np.ndarray): each plasmid's expected depletion rate.
        all_pvalues (np.ndarray): the p-values of every motif the scan tested.
        log2fc_thr, q_threshold, score_thr: as for `_annotate_significance`.
        min_support (int): as for `_classify_positions` and `_annotate_significance`.
        totals (dict): as for `_classify_positions`.

    Returns:
        pd.DataFrame: `table` with a 'merged_from' column -- the replaced motifs joined by '+', empty
        for every other row -- and the merged rows in place of those they replaced, called rows
        first. A table with no merge comes back as it was, with the column added.
    """
    table = table.assign(merged_from="")
    called = table[table["called"]]
    fc = log2fc_series.to_numpy(dtype=float)
    totals = {} if totals is None else totals
    grown = {}                                       # canonical merged motif -> (spelling, pattern)
    for motif, pattern in zip(called["motif"], _patterns(called)):
        merged = _generalise_motif(motif, pattern, encoded, fc, background, log2fc_thr,
                                  min_support, totals)
        if merged != motif:
            grown.setdefault(canonical_motif(merged), (merged, pattern))
    keep = [m for m in grown if not any(o != m and _is_instance(m, o) for o in grown)]
    if not keep:
        return table
    rows = _motif_rows([grown[m][0] for m in keep], [grown[m][1] for m in keep], log2fc_series,
                       left_context, right_context, encoded, log2fc_thr)
    scored = _annotate_significance(_canonicalise_motifs(rows), log2fc_series, left_context,
                                   right_context, all_pvalues=all_pvalues, log2fc_thr=log2fc_thr,
                                   q_threshold=q_threshold, encoded=encoded,
                                   background=background, score_thr=score_thr,
                                   min_support=min_support)
    scored = scored[scored["called"]]
    if scored.empty:
        return table
    absorbable = table["called"] | _junction_dependent(table, score_thr, min_support, q_threshold)
    pool = table[absorbable].sort_values("q_value", kind="stable")["motif"]
    absorbed = [[m for m in pool if _is_instance(m, g)] for g in scored["motif"]]
    scored = scored.assign(merged_from=["+".join(a) for a in absorbed])
    dropped = absorbable & table["motif"].isin([m for a in absorbed for m in a])
    out = pd.concat([table[~dropped], scored[table.columns]], ignore_index=True)
    return out.sort_values(["called", "q_value"], ascending=[False, True], kind="stable")

# %% ../nbs/00_core.ipynb #66eeb538
def call_reason(
    row:pd.Series, # a row of the result table with every column (`all_motifs=True`)
    q_threshold:float=0.05, # a call needs q below this
    score_thr:float=0.5, # and the lower bound on the depleted fraction at this or above
    min_support:int=5, # a motif that needs the flanks needs this many internal carriers
)->str: # "called", or each failed test with its numbers; a bimodal call adds a note
    "Why a row of the result table is called or not, in a few words."
    n = int(row["num_sequences"])
    failed = []
    if not row["q_value"] < q_threshold:
        failed.append(f"not significant (q = {row['q_value']:.2g})")
    if not row["fraction_depleted_lower"] >= score_thr:
        failed.append(f"most carriers not shown depleted ({round(row['fraction_depleted'] * n)}/{n}; "
                      f"lower bound {row['fraction_depleted_lower']:.2f} < {score_thr:g})")
    if _junction_dependent(row, score_thr, min_support, q_threshold):
        failed.append(f"junction-dependent: {row['junction_share']:.0%} of carriers need the flank, "
                      f"and its internal sites do not reach the bar (n = {int(row['internal_n'])}, "
                      f"lower bound {row['internal_fraction_lower']:.2f}, "
                      f"p = {row['internal_p_value']:.2g})")
    if failed:
        return "; ".join(failed)
    return "called; carriers split between depleted and untouched" if row["bimodal"] else "called"


_COMPACT_COLUMNS = ["motif", "num_sequences", "fraction_depleted", "avg_log2fc", "q_value"]
_FULL_COLUMNS = _COMPACT_COLUMNS + ["pattern", "fraction_depleted_lower", "background", "p_value",
                                    "called", "bimodality", "bimodal", "junction_share", "internal_n",
                                    "internal_fraction_lower", "internal_p_value", "merged_from"]


def _result_view(table, all_motifs, q_threshold, score_thr, min_support):
    """What `find_restricted_motifs` returns: the called rows in five columns, or every row with
    its `reason`, called first."""
    if not all_motifs:
        return (table.loc[table["called"], _COMPACT_COLUMNS]
                .sort_values(["q_value", "motif"]).reset_index(drop=True))
    reason = [call_reason(r, q_threshold, score_thr, min_support) for _, r in table.iterrows()]
    return (table[_FULL_COLUMNS].assign(reason=pd.Series(reason, index=table.index, dtype=object))
            .sort_values(["called", "q_value", "motif"], ascending=[False, True, True])
            .reset_index(drop=True))

# %% ../nbs/00_core.ipynb #3bfb4529
class TooManyCandidatesError(RuntimeError):
    "Raised when step 3 leaves more candidates than step 4 will compare."

    def __init__(self,
                 n_candidates:int, # how many candidates step 3 left; kept as `.n_candidates`
                 max_candidates:int, # the limit they exceed; kept as `.max_candidates`
                 log2fc_thr:float, # the run's thresholds, quoted in the message
                 score_thr:float, # quoted in the message
                 min_support:int, # quoted in the message
                 candidates:pd.DataFrame, # step 3's candidate table; kept as `.candidates`
                ):
        self.n_candidates = n_candidates
        self.max_candidates = max_candidates
        self.candidates = candidates
        super().__init__(
            f"Too many candidate motifs: {n_candidates} > max_candidates={max_candidates}. "
            f"Step 4 compares candidates with each other and would not finish. This usually "
            f"means the thresholds are too permissive for this sample: check that the log2FC are "
            f"median-normalised, as calculate_log2fc returns them, "
            f"or try a stricter log2fc_thr (currently {log2fc_thr}, e.g. -1.0), "
            f"score_thr (currently {score_thr}, e.g. 0.7), or "
            f"min_support (currently {min_support}, e.g. 10). "
            f"Raise max_candidates only if you know why this strain has so many candidates. "
            f"Step 3's candidates are on this exception as `.candidates`."
        )

# %% ../nbs/00_core.ipynb #e7d6ec42
def find_restricted_motifs(
    log2fc_series:pd.Series, # log2FC indexed by insert, median-normalised (`calculate_log2fc`)
    left_context_str:str, # vector sequence 5' of the insert
    right_context_str:str, # vector sequence 3' of the insert
    n_jobs:int=1, # processes scanning the patterns; 1 scans in this process
    patterns:list|None=None, # `(d1, spacer, d2)` shapes to search, or one; default `get_patterns()`
    log2fc_thr:float=-0.5, # a plasmid counts as depleted below this
    min_support:int=5, # fewest carriers a motif is scored on
    score_thr:float=0.5, # share of carriers a candidate needs depleted, and a call its lower bound
    max_candidates:int=5000, # most candidates step 3 may hand to step 4; past it, raise
    q_threshold:float=0.05, # a motif is called when its q-value is below this
    encoded_library:tuple|None=None, # the library from `encode_library`, if already encoded
    all_motifs:bool=False, # return every scored motif with every column, not only the calls
    verbose:bool=False, # also print each candidate set aside or removed, and each motif scored
)->pd.DataFrame: # the called motifs, one row each (*Reading the result table*)
    "The motifs one sample restricts: steps 2 to 4 and reporting, on a log2FC series."
    candidates = pd.DataFrame(columns=['motif', 'fraction_depleted', 'num_sequences',
                                       'avg_log2fc', 'pattern'])
    report = functools.partial(_annotate_significance, log2fc_thr=log2fc_thr,
                               q_threshold=q_threshold, score_thr=score_thr,
                               min_support=min_support)
    view = functools.partial(_result_view, all_motifs=all_motifs, q_threshold=q_threshold,
                             score_thr=score_thr, min_support=min_support)
    if log2fc_series.empty:
        print("The input series is empty; there is nothing to scan.")
        return view(report(candidates, log2fc_series, left_context_str, right_context_str,
                           all_pvalues=np.array([])).assign(merged_from=""))

    # The library is encoded once and every step below reads it.
    if encoded_library is None:
        encoded_library = encode_library(get_lib_seq_context(
            log2fc_series.index.tolist(), left_context_str, right_context_str))
    elif encoded_library[0].shape[0] != len(log2fc_series):
        raise ValueError(
            f"encoded_library holds {encoded_library[0].shape[0]} sequences but log2fc_series "
            f"has {len(log2fc_series)}; it must encode exactly this series' index, in order, "
            f"with these flanks.")
    fc = log2fc_series.to_numpy(dtype=float)
    background = plasmid_background(log2fc_series.index, fc, log2fc_thr)

    if patterns is None:
        patterns = get_patterns()
    elif np.ndim(patterns) == 1:          # one pattern rather than a list
        patterns = [patterns]
    # A pattern and its mirror find the same sites (the scan reads both strands), and a gapless
    # pattern is one run however it is split, so each is searched once, in canonical form.
    for p, c in sorted({(tuple(p), _canonical_pattern(p)) for p in patterns
                        if tuple(p) != _canonical_pattern(p)}):
        print(f"Pattern {p} is searched as {c}: the same sites, read on the other strand.")
    patterns = sorted({_canonical_pattern(p) for p in patterns},
                                     key=lambda x: (x[0] + x[2], x[1], x))

    # Step 2.
    worker = functools.partial(
        _scan_candidates, encoded_library=encoded_library,
        fc_values=fc, background=background, log2fc_thr=log2fc_thr,
        score_thr=score_thr, min_support=min_support)
    if n_jobs == 1:
        per_pattern = [worker(p) for p in tqdm(patterns, desc="Scanning patterns")]
    else:
        # Each worker scans single-threaded: n_jobs processes each starting numba's thread pool
        # would ask for n_jobs x cores at once. imap keeps pattern order, so the result does not
        # depend on which worker finishes first.
        with Pool(processes=n_jobs) as pool:
            per_pattern = list(tqdm(pool.imap(functools.partial(worker, parallel=False),
                                              patterns),
                                    total=len(patterns), desc="Scanning patterns"))

    tested_pvalues = (np.concatenate([pv for _, pv, _ in per_pattern]) if per_pattern
                      else np.array([]))
    # The p-value a motif needs to be called: the largest that clears q_threshold over every
    # motif tested. Step 4 holds the candidates' leftovers to it, since they were selected
    # from that same pool.
    _q = _benjamini_hochberg(tested_pvalues)
    scan_cutoff = tested_pvalues[_q < q_threshold].max() if (_q < q_threshold).any() else 0.0
    hits = [df for df, _, _ in per_pattern if not df.empty]
    totals = {p: t for p, (_, _, t) in zip(patterns, per_pattern)}

    # Step 3, once over every pattern's candidates. It scores variants from the scan's counts,
    # so a pattern step 2 scanned is never rescanned.
    if hits:
        candidates = _filter_redundant_patterns(
            pd.concat(hits, ignore_index=True), log2fc_series,
            left_context_str, right_context_str,
            log2fc_thr=log2fc_thr, score_thr=score_thr,
            min_support=min_support, encoded=encoded_library, totals=totals,
            background=background)
        print(f"{sum(len(h) for h in hits)} candidate(s) across all patterns; "
              f"{len(candidates)} remain after step 3.")
    if len(candidates) > max_candidates:
        raise TooManyCandidatesError(len(candidates), max_candidates, log2fc_thr,
                                     score_thr, min_support,
                                     candidates)

    # Each candidate's carriers, and those with a site inside the insert, are read once: the flank
    # check, step 4 and the report take their columns.
    carriers = _carriers(encoded_library, candidates["motif"].tolist(), _patterns(candidates),
                         log2fc_series, left_context_str, right_context_str, inside=True)
    scanned = candidates.index
    columns_of = lambda rows: tuple(c[:, scanned.get_indexer(rows.index)] for c in carriers)

    # Sites completed by the flank, set aside before step 4 can let them explain other candidates.
    candidates, flank_only = _filter_junction_dependent(
        candidates, log2fc_series, left_context_str, right_context_str,
        log2fc_thr=log2fc_thr, score_thr=score_thr, min_support=min_support,
        q_threshold=q_threshold, p_threshold=scan_cutoff, background=background,
        carriers=carriers)
    if len(flank_only):
        print(f"{len(flank_only)} candidate(s) that need the vector flanks, without enough "
              f"internal sites ({int(flank_only['listed'].sum())} would otherwise be called).")
        if verbose:
            for m, s, n, lo, c in sorted(zip(flank_only["motif"].map(canonical_motif),
                                             flank_only["junction_share"], flank_only["internal_n"],
                                             flank_only["internal_fraction_lower"],
                                             flank_only["listed"])):
                print(f"    {m} ({s:.0%} of carriers need the flank; {n} internal, "
                      f"lower bound {lo:.2f}){' -- would otherwise be called' if c else ''}")

    # Step 4.
    candidates, explained = _filter_explained_candidates(
        candidates, log2fc_series, left_context_str, right_context_str,
        log2fc_thr=log2fc_thr, score_thr=score_thr,
        min_support=min_support, p_threshold=scan_cutoff, background=background,
        presence=columns_of(candidates)[0])
    if explained:
        print(f"{len(explained)} candidate(s) whose score was borrowed from a stronger one.")
        if verbose:
            for m, (by, n, s) in sorted(explained.items()):
                print(f"    {m} <- {by} (without them: n={n}, score={s:.2f})")

    # The candidates set aside for the flanks that would otherwise be called: reported, not called.
    if len(flank_only):
        candidates = pd.concat([candidates, flank_only.loc[flank_only["listed"], candidates.columns]])
    # Canonicalise before printing, so the names in the log are the names in the table.
    candidates = _canonicalise_motifs(candidates)
    print(f"{len(candidates)} motif(s) scored.")
    if verbose:
        for _, row in candidates.iterrows():
            print(f"  {row['motif']} (pattern {row['pattern']}), "
                  f"FracDep: {row['fraction_depleted']:.2f}, "
                  f"AvgFC: {row['avg_log2fc']:.2f}, N: {row['num_sequences']}")
    table = report(candidates, log2fc_series, left_context_str, right_context_str,
                   all_pvalues=tested_pvalues, background=background,
                   carriers=columns_of(candidates))

    # A degenerate site's called variants, reported as one IUPAC motif.
    table = _merge_degenerate_calls(
        table, log2fc_series, left_context_str, right_context_str, encoded_library, background,
        tested_pvalues, log2fc_thr=log2fc_thr, q_threshold=q_threshold,
        score_thr=score_thr, min_support=min_support, totals=totals)
    merged = table[table["merged_from"] != ""]
    if len(merged):
        print(f"{len(merged)} degenerate site(s) reported as one motif:")
        for m, parts in zip(merged["motif"], merged["merged_from"]):
            print(f"  {m} <- {parts.replace('+', ' + ')}")
    print(f"{int(table['called'].sum())} motif(s) called.")
    return view(table)
